/// <summary>
///     The <c>NDX_KBVJobProt</c> is the exetension class for table <c>common</c>
/// </summary>
public class NDX_KBVJobProt extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>createProt</c> method.
/// </summary>
/// <param name="nDX_KBVJob">
///    <c>NDX_KBVJob</c> as type
/// </param>
/// <param name="lJobMode">
///    <c>boolean</c> as type
/// </param>
/// <param name="lStartTime">
///    <c>boolean</c> as type
/// </param>
public void createProt( NDX_KBVJob  nDX_KBVJob,
                        boolean     lJobMode,
                        boolean     lStartTime  = true)
{
    UtcDateTime     dateTime;

    this.selectForUpdate(true);

    this.NDX_KBVJob = nDX_KBVJob;

    if(lJobMode)
    {
        this.NDX_KBVJobMode = NDX_KBVJobMode::KBV_Job;
    }
    else
    {
        this.NDX_KBVJobMode = NDX_KBVJobMode::KBV_Manual;
    }

    dateTime                = DateTimeUtil::getSystemDateTime();

    if(lStartTime)
    {
        this.StartDateTime  = dateTime;
    }
    else
    {
        this.EndDateTime    = dateTime;
    }

    ttsbegin;
    this.write();
    ttscommit;
}

/// <summary>
///    AVA <c>duration</c> method.
/// </summary>
/// <returns>
///    <c>NDX_DayTimeString</c> as return value
/// </returns>
display NDX_DayTimeString duration()
{
    NDX_DayTimeString   retVal;

    int                 nSeconds;

    if(this.EndDateTime)
    {
        nSeconds    = int642int(DateTimeUtil::getDifference(this.EndDateTime, this.StartDateTime));
        retVal      = NDXHelperCommon::seconds2Str(nSeconds);
    }
    else
    {
        retVal      = '';
    }
    return retVal;
}
